[Form]
public final class METPurchLineOpenOrder extends FormRun implements SysIFilterConsumerForm,SysIFilterEventHandler, METItemInquiryFilerProvider
{
    FormRun caller1;

}

/// <summary>
/// Initialize the filter consumer form.
/// </summary>
void init()
{
    caller1 = element.args().caller() as FormRun;

    super();

    purchTable_ds.query().dataSourceTable(tablenum(PurchTable)).addRange(fieldnum(PurchTable, PurchStatus)).value(enum2Value(PurchStatus::Backorder));
    purchLine_ds.query().dataSourceTable(tablenum(PurchLine)).addRange(fieldnum(PurchLine, PurchaseType)).value(queryValue(PurchaseType::ReturnItem));
    purchLine_ds.query().dataSourceTable(tablenum(PurchLine)).addRange(fieldnum(PurchLine, PurchaseType)).value(queryValue(PurchaseType::Purch));
    purchLine_ds.query().dataSourceTable(tablenum(PurchLine)).addRange(fieldnum(PurchLine, PurchStatus)).value(enum2Value(PurchStatus::Backorder));

    if (element.args().record())
    {
        purchLine_ds.object(fieldnum(PurchLine, VendAccount)).visible(false);
    }
}

/// <summary>
/// Register the data source to which the filter should be applied.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    PurchLine_ds.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

/// <summary>
/// Parameter method to get the ItemId filter from the filter form.
/// </summary>
/// <returns>ItemId</returns>
public ItemId parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(ItemId));

}

/// <summary>
/// Event handler to react on a filter change.
/// </summary>
public void onFilterChanged()
{
    PurchLine_ds.research();

    PurchLine_ds.executeQuery();

}

/// <summary>
/// Parameter method to get the InventLocationId filter from the filter form.
/// </summary>
/// <returns></returns>
public InventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(InventLocationId));
}

/// <summary>
/// Execute the query with the applied filters.
/// </summary>
public void executeQuery()
{
    QueryBuildRange rangeIsDeleted = this.query().dataSourceTable(tablenum(PurchLine)).addRange(fieldnum(PurchLine,IsDeleted));
    rangeIsDeleted.value(SysQuery::value(NoYes::No));
    rangeIsDeleted.status(RangeStatus::Hidden);

    ItemId              itemIdFilter =  caller1.parmItemId();
    InventLocationId    inventLocationIdFilter = caller1.parminventoryLocationId();

    if (caller1)
    {
        QueryBuildDataSource  qbdsLoc = this.queryBuildDataSource();
        qbdsLoc.clearRanges();
        qbdsLoc.addRange(fieldNum(PurchLine, ItemId)).value(itemIdFilter);
    }
    super();

}

/// <summary>
/// Execute the query with the applied filters.
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource qbdsPurchTable = this.query().dataSourceTable(tableNum(InventDim));
    if (qbdsPurchTable)
    {
        InventLocationId    inventLocationIdFilter = caller1.parminventoryLocationId();
        if (inventLocationIdFilter)
        {
            qbdsPurchTable.addRange(fieldNum(InventDim, InventLocationId)).value(inventLocationIdFilter);
        }

        else
        {
            qbdsPurchTable.clearRange(fieldNum(InventDim, InventLocationId));
        }
    }
    super();
}

/// <summary>
/// Initialize the query with the applied filters.
/// </summary>
public void init()
{
    super();

    QueryBuildDataSource    qbds                    = this.query().dataSourceTable(this.table());
    QueryBuildRange         rangeIsDeletedSchedule  = qbds.addRange(fieldnum(PurchDeliverySchedule, IsDeleted));

    rangeIsDeletedSchedule.value(SysQuery::value(NoYes::No));
    rangeIsDeletedSchedule.status(RangeStatus::Hidden);

    qbds.clearLinks();
    qbds.clearDynalinks();
    qbds.addLink(fieldNum(PurchLine, InventTransId), fieldNum(PurchDeliverySchedule, OrderLine));          
}
